mapper.select:
select dt.* from dimension_tag dt
                     inner join dimension_tag_image_relation dtir on dt.id = dtir.tag_id
where dtir.image_id = #{id}

select dic.* from dimension_image_category dic
                      inner join dimension_image di on dic.id = di.category_id
where di.id = #{imageId}

select count(distinct dtir.image_id) from dimension_tag_image_relation dtir
                                              inner join dimension_tag dt on dtir.tag_id = dt.id
where dt.name like #{keyword}

mapper.update:
update dimension_image
set votes = votes - 1
where id = #{imageId}

update dimension_image
set comments = comments + 1
where id = #{imageId}

update dimension_image
set category_id = #{categoryId}
where id = #{imageId}

update dimension_image_category
set count = count + 1
where id = #{categoryId}

update dimension_image
set score = #{score}
where id = #{imageId}

mapper.select:
SELECT * FROM dimension_image
WHERE category_id = #{categoryId} AND status = 1
ORDER BY score DESC LIMIT #{pageNum}, #{pageSize}

